insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (10741, 41, 'Sirenennetz ausbauen, modernisieren und an digitale Warnsysteme (MoWaS, Apps) anbinden (Land)', 'Warntag-Befragungen zeigen, dass der Mix aus Sirenen, Cell Broadcast und Apps fast alle erreicht; Sirenen erreichen rund 59 % und wirken auch bei Netzausfall. Dagegen: Cell Broadcast erreicht bereits die meisten, der Zusatznutzen weiterer Sirenen ist begrenzt.', 'belegt', 'https://www.l-iz.de/melder/wortmelder/2024/09/vorlaeufige-befragungsergebnisse-bundesweiter-warntag-2024-hat-95-prozent-der-buergerinnen-und-buerger-erreicht-603092', 'land', null, true, 'blind'),
  (10742, 41, 'Bundesförderung für den Ausbau der Warninfrastruktur, insbesondere Sirenen (Bund)', 'Der Bund ist für die Warnung im Zivilschutz zuständig und hat Sirenen bereits gefördert; der Warnmittelmix erreicht laut Warntag-Befragungen fast alle. Dagegen: Umfang der Förderung offen, Umsetzung hängt von Ländern und Kommunen ab.', 'belegt', 'https://www.l-iz.de/melder/wortmelder/2024/09/vorlaeufige-befragungsergebnisse-bundesweiter-warntag-2024-hat-95-prozent-der-buergerinnen-und-buerger-erreicht-603092', 'bund', null, true, 'blind'),
  (10743, 41, 'Aufklärung und Angebote zur Selbsthilfe und Krisenvorsorge der Bevölkerung (Bund)', 'Eine Meta-Analyse findet einen kleinen Effekt auf Vorsorgeverhalten, aber keinen signifikanten auf Vorräte und Wissen, bei sehr geringer Evidenzsicherheit. Dafür spricht: günstig und schnell umsetzbar.', 'gemischt', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11003604', 'bund', null, true, 'blind')
