  (41, 12, 'BE', 'keine', 'Kapitel Sicherheit für ein gutes Leben, Abschnitte Infrastruktur-, Bevölkerungs- und Katastrophenschutz sowie Schutz und Sicherheit für Stadt und Menschen (S. 28–30) gelesen; nichts zu Sirenen, Warn-Apps, Cell Broadcast oder MoWaS.', '2026-10-21', true, '{4102}'),
  (41, 12, 'MV', 'keine', 'Kapitel Katastrophen- und Zivilschutz (S. 49–50) und Sicherheit (S. 45–46) gelesen, Stichwortsuche Sirene, MoWaS, Warnsystem, Warn-App, Cell Broadcast. Nichts zu Sirenen oder Warnweg; Schutzräume (S. 49) und Eigenvorsorge (S. 50) betreffen andere Ursachen.', '2026-10-21', true, '{4102}'),
