  (41, 13, 'BE', 'keine', 'Kapitel 6.2 Bevölkerungs- und Katastrophenschutz (S. 235–237) und Fundstellen S. 139, 210 gelesen; nichts zum Warnweg (Sirenen, MoWaS, Warn-Apps, Cell Broadcast). Frühwarnsysteme (S. 139, 210) betreffen Antisemitismus und Drogen.', '2026-10-21', true, '{4102}'),
  (41, 13, 'MV', 'keine', 'Kapitel 17.3 „Gemeinsam für Sicherheit und Resilienz im Ostseeraum“ (S. 109–110) gelesen: Krisenvorsorge, Katastrophenschutz und Resilienzpläne, aber nichts zu Warnwegen, Sirenen oder Warn-Apps. Klimaanpassung (S. 11) nur Schutz vor Starkregen und Hochwasser, keine Warnung. Suche im ganzen Text (Warn, Sirene, MoWaS, Cell Broadcast, Alarm, Notruf) ohne Treffer.', '2026-10-21', true, '{4102}'),
  (41, 13, 'ST', 'keine', 'Erfasste Stellen (S. 48) setzen laut Bewertung ohne Parteinamen an keiner der Ursachen an.', '2026-10-21', true, '{4102}'),
  (41, 14, null, 'keine', 'Kapitel Innere Sicherheit (S. 21–24), Föderalismus (S. 36), Verteidigung (S. 46–47) gelesen und Volltextsuche nach Schutzraum, Sirene, Warn, Vorrat, Bevölkerungsschutz; nichts zu Schutzorten, Warnweg oder Notvorräten.', '2026-10-21', true, '{4101,4102,4103}'),
