  (41, 15, 'ST', 'keine', 'Kapitel VI „Innere Sicherheit“ (S. 113–114, Katastrophenschutz), Energiepolitik (S. 160–161, Blackout-Strategie), Hochwasserschutz (S. 205) und Pandemie-Krisenplan (S. 247) gelesen; nichts zu Sirenen, MoWaS, Warn-Apps, Cell Broadcast oder Warnweg.', '2026-10-21', true, '{4102}'),
  (41, 16, null, 'keine', 'Erfasste Stellen (S. 33) setzen laut Bewertung ohne Parteinamen an keiner der Ursachen an.', '2026-10-21', true, '{4101,4102,4103}'),
  (41, 16, 'BE', 'keine', 'Kapitel Inneres, Abschnitt Bevölkerungsschutz (S. 297–299) gelesen: Katastrophenschutz, Notunterbringung, Notstrom, Läufer*innen für Information; kein Warnweg (Sirenen, MoWaS, Warn-Apps, Cell Broadcast). Stichwortsuche im Gesamttext ohne Treffer.', '2026-10-21', true, '{4102}'),
  (41, 16, 'MV', 'keine', 'Erfasste Stellen (S. 20) setzen laut Bewertung ohne Parteinamen an keiner der Ursachen an.', '2026-10-21', true, '{4102}'),
  (41, 16, 'ST', 'keine', 'Kapitel Katastrophen- und Bevölkerungsschutz (S. 130–133) gelesen, dazu Kapitel Innenpolitik-Einstieg und Stichwortsuche. Nichts zu Sirenen, MoWaS, Warn-Apps, Cell Broadcast oder Lücken im Warnweg; Leuchttürme und Selbstvorsorge (S. 131) betreffen Schutzorte und Vorbereitung, keine Warnung.', '2026-10-21', true, '{4102}'),
  (41, 17, null, 'keine', 'Erfasste Stellen (S. 20, 13) setzen laut Bewertung ohne Parteinamen an keiner der Ursachen an.', '2026-10-21', true, '{4101,4102,4103}'),
  (41, 17, 'BE', 'keine', 'Kapitel Gesundheit (S. 25), Innere Sicherheit (S. 38–41) und Kriegswirtschaft (S. 44) gelesen; nichts zu Sirenen, MoWaS, Warn-Apps oder Cell Broadcast. Warnsystem S. 40 betrifft Betroffene häuslicher Gewalt.', '2026-10-21', true, '{4102}'),
  (41, 17, 'MV', 'keine', 'Kapitel ''Schutz der Bevölkerung vor den Folgen von Kriegen'' (S. 7–8) und ''Feuerwehr, Rettungsdienste und Katastrophenschutz'' (S. 68) gelesen; nichts zu Sirenen, Warnsystem, Warn-Apps oder Cell Broadcast. Klimaanpassung (S. 86) betrifft Wasservorsorge, keine Warnung.', '2026-10-21', true, '{4102}'),
  (41, 17, 'ST', 'keine', 'Kapitel „Schutz beginnt vor der Katastrophe“ (S. 68–69) und Kapitel „Schutz ist staatliche Kernaufgabe“ (S. 66–67) gelesen; nichts zu Sirenen, MoWaS, Warn-Apps oder Cell Broadcast.', '2026-10-21', true, '{4102}');
